import requests
import json
import sys
import os

URL = "http://are-sidecar:8000/mcp"
SESSION_FILE = "/tmp/mcp_session"

def parse_sse(text):
    # take last data line
    last = None
    for line in text.split('\n'):
        if line.startswith('data: '):
            last = json.loads(line[6:])
    return last

def init_session():
    headers = {'Content-Type':'application/json','Accept':'application/json, text/event-stream'}
    payload = {"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"cli","version":"1.0"}}}
    r = requests.post(URL, headers=headers, json=payload)
    sid = r.headers.get('mcp-session-id')
    with open(SESSION_FILE,'w') as f:
        f.write(sid)
    h2 = dict(headers); h2['mcp-session-id']=sid
    requests.post(URL, headers=h2, json={"jsonrpc":"2.0","method":"notifications/initialized"})
    return sid

def get_session():
    if os.path.exists(SESSION_FILE):
        return open(SESSION_FILE).read().strip()
    return init_session()

_id_counter = [10]
def call(method, params=None):
    _id_counter[0] += 1
    sid = get_session()
    headers = {'Content-Type':'application/json','Accept':'application/json, text/event-stream','mcp-session-id':sid}
    payload = {"jsonrpc":"2.0","id":_id_counter[0],"method":method}
    if params is not None:
        payload["params"] = params
    r = requests.post(URL, headers=headers, data=json.dumps(payload))
    if 'text/event-stream' in r.headers.get('content-type',''):
        return parse_sse(r.text)
    try:
        return r.json()
    except:
        return r.text

def tool(name, args=None):
    res = call("tools/call", {"name":name,"arguments":args or {}})
    # extract result text
    try:
        text = res['result']['content'][0]['text']
        return json.loads(text)
    except Exception as e:
        return res

if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "init":
        print(init_session())
    elif cmd == "list":
        print(json.dumps(call("tools/list"), indent=2))
    elif cmd == "call":
        name = sys.argv[2]
        args = json.loads(sys.argv[3]) if len(sys.argv)>3 else {}
        print(json.dumps(tool(name,args), indent=2))
